"867 :   private void updateTypeOfParametersOnClosure(Node n, FunctionType fnType) {
868 :     int i = 0;
869 :     int childCount = n.getChildCount();
870 :     for (Node iParameter : fnType.getParameters()) {
871 :       JSType iParameterType = iParameter.getJSType();
872 :       if (iParameterType instanceof FunctionType) {
873 :         FunctionType iParameterFnType = (FunctionType) iParameterType;
874 : 
875 :         if (i + 1 >= childCount) {
876 :           // TypeCheck#visitParametersList will warn so we bail.
877 :           return;
878 :         }
879 :         Node iArgument = n.getChildAtIndex(i + 1);
880 :         JSType iArgumentType = getJSType(iArgument);
881 :         if (iArgument.getType() == Token.FUNCTION &&
882 :             iArgumentType instanceof FunctionType &&
883 :             iArgument.getJSDocInfo() == null) {
884 :           iArgument.setJSType(iParameterFnType);
885 :         }
886 :       }
887 :       i++;
888 :     }
889 :   }"

"1629 :   private void visitReturn(NodeTraversal t, Node n) {
1630 :     Node function = t.getEnclosingFunction();
1631 : 
1632 :     // This is a misplaced return, but the real JS will fail to compile,
1633 :     // so let it go.
1634 :     if (function == null) {
1635 :       return;
1636 :     }
1637 :     JSType jsType = getJSType(function);
1638 : 
1639 :     if (jsType instanceof FunctionType) {
1640 :       FunctionType functionType = (FunctionType) jsType;
1641 : 
1642 :       JSType returnType = functionType.getReturnType();
1643 : 
1644 :       // if no return type is specified, undefined must be returned
1645 :       // (it's a void function)
1646 :       if (returnType == null) {
1647 :         returnType = getNativeType(VOID_TYPE);
1648 :       }
1649 : 
1650 :       // fetching the returned value's type
1651 :       Node valueNode = n.getFirstChild();
1652 :       JSType actualReturnType;
1653 :       if (valueNode == null) {
1654 :         actualReturnType = getNativeType(VOID_TYPE);
1655 :         valueNode = n;
1656 :       } else {
1657 :         actualReturnType = getJSType(valueNode);
1658 :       }
1659 : 
1660 :       // verifying
1661 :       validator.expectCanAssignTo(t, valueNode, actualReturnType, returnType,
1662 :           "inconsistent return type");
1663 :     }
1664 :   }"

"1362 :   private void visitVar(NodeTraversal t, Node n) {
1363 :     // TODO(nicksantos): Fix this so that the doc info always shows up
1364 :     // on the NAME node. We probably want to wait for the parser
1365 :     // merge to fix this.
1366 :     JSDocInfo varInfo = n.hasOneChild() ? n.getJSDocInfo() : null;
1367 :     for (Node name : n.children()) {
1368 :       Node value = name.getFirstChild();
1369 :       // A null var would indicate a bug in the scope creation logic.
1370 :       Var var = t.getScope().getVar(name.getString());
1371 : 
1372 :       if (value != null) {
1373 :         JSType valueType = getJSType(value);
1374 :         JSType nameType = var.getType();
1375 :         nameType = (nameType == null) ? getNativeType(UNKNOWN_TYPE) : nameType;
1376 : 
1377 :         JSDocInfo info = name.getJSDocInfo();
1378 :         if (info == null) {
1379 :           info = varInfo;
1380 :         }
1381 :         if (info != null && info.hasEnumParameterType()) {
1382 :           // var.getType() can never be null, this would indicate a bug in the
1383 :           // scope creation logic.
1384 :           checkEnumInitializer(
1385 :               t, value,
1386 :               info.getEnumParameterType().evaluate(t.getScope(), typeRegistry));
1387 :         } else if (var.isTypeInferred()) {
1388 :           ensureTyped(t, name, valueType);
1389 :         } else {
1390 :           validator.expectCanAssignTo(
1391 :               t, value, valueType, nameType, "initializing variable");
1392 :         }
1393 :       }
1394 :     }
