"1020 :     void defineSlot(Node n, Node parent, String variableName,
1021 :         JSType type, boolean inferred) {
1022 :       Preconditions.checkArgument(!variableName.isEmpty());
1023 : 
1024 :       boolean isGlobalVar = n.getType() == Token.NAME && scope.isGlobal();
1025 :       boolean shouldDeclareOnGlobalThis =
1026 :           isGlobalVar &&
1027 :           (parent.getType() == Token.VAR ||
1028 :            parent.getType() == Token.FUNCTION);
1029 : 
1030 :       // If n is a property, then we should really declare it in the
1031 :       // scope where the root object appears. This helps out people
1032 :       // who declare "global" names in an anonymous namespace.
1033 :       Scope scopeToDeclareIn = scope;
1034 :       if (n.getType() == Token.GETPROP && !scope.isGlobal() &&
1035 :           isQnameRootedInGlobalScope(n)) {
1036 :         Scope globalScope = scope.getGlobalScope();
1037 : 
1038 :         // don't try to declare in the global scope if there's
1039 :         // already a symbol there with this name.
1040 :         if (!globalScope.isDeclared(variableName, false)) {
1041 :           scopeToDeclareIn = scope.getGlobalScope();
1042 :         }
1043 :       }
1044 : 
1045 :       // declared in closest scope?
1046 :       if (scopeToDeclareIn.isDeclared(variableName, false)) {
1047 :         Var oldVar = scopeToDeclareIn.getVar(variableName);
1048 :         validator.expectUndeclaredVariable(
1049 :             sourceName, n, parent, oldVar, variableName, type);
1050 :       } else {
1051 :         if (!inferred) {
1052 :           setDeferredType(n, type);
1053 :         }
1054 :         CompilerInput input = compiler.getInput(sourceName);
1055 :         boolean isExtern = input.isExtern();
1056 :         Var newVar =
1057 :             scopeToDeclareIn.declare(variableName, n, type, input, inferred);
1058 : 
1059 :         if (shouldDeclareOnGlobalThis) {
1060 :           ObjectType globalThis =
1061 :               typeRegistry.getNativeObjectType(GLOBAL_THIS);
1062 :           if (inferred) {
1063 :             globalThis.defineInferredProperty(variableName,
1064 :                 type == null ?
1065 :                     getNativeType(JSTypeNative.NO_TYPE) :
1066 :                     type,
1067 :                 isExtern, n);
1068 :           } else {
1069 :             globalThis.defineDeclaredProperty(variableName, type, isExtern, n);
1070 :           }
1071 :         }
1072 : 
1073 :         if (type instanceof EnumType) {
1074 :           Node initialValue = newVar.getInitialValue();
1075 :           boolean isValidValue = initialValue != null &&
1076 :               (initialValue.getType() == Token.OBJECTLIT ||
1077 :                initialValue.isQualifiedName());
1078 :           if (!isValidValue) {
1079 :             compiler.report(JSError.make(sourceName, n, ENUM_INITIALIZER));
1080 :           }
1081 :         }
1082 : 
1083 :         // We need to do some additional work for constructors and interfaces.
1084 :         if (type instanceof FunctionType &&
1085 :             // We don't want to look at empty function types.
1086 :             !type.isEmptyType()) {
1087 :           FunctionType fnType = (FunctionType) type;
1088 :           if ((fnType.isConstructor() || fnType.isInterface()) &&
1089 :               !fnType.equals(getNativeType(U2U_CONSTRUCTOR_TYPE))) {
1090 :             // Declare var.prototype in the scope chain.
1091 :             FunctionType superClassCtor = fnType.getSuperClassConstructor();
1092 :             scopeToDeclareIn.declare(variableName + ".prototype", n,
1093 :                 fnType.getPrototype(), input,
1094 :                 /* declared iff there's an explicit supertype */
1095 :                 superClassCtor == null ||
1096 :                 superClassCtor.getInstanceType().equals(
1097 :                     getNativeType(OBJECT_TYPE)));
1098 : 
1099 :             // Make sure the variable is initialized to something if
1100 :             // it constructs itself.
1101 :             if (newVar.getInitialValue() == null &&
1102 :                 !isExtern &&
1103 :                 // We want to make sure that when we declare a new instance
1104 :                 // type (with @constructor) that there's actually a ctor for it.
1105 :                 // This doesn't apply to structural constructors
1106 :                 // (like function(new:Array). Checking the constructed
1107 :                 // type against the variable name is a sufficient check for
1108 :                 // this.
1109 :                 variableName.equals(
1110 :                     fnType.getInstanceType().getReferenceName())) {
1111 :               compiler.report(
1112 :                   JSError.make(sourceName, n,
1113 :                       fnType.isConstructor() ?
1114 :                           CTOR_INITIALIZER : IFACE_INITIALIZER,
1115 :                       variableName));
1116 :             }
1117 :           }
1118 :         }
1119 :       }
1120 : 
1121 :       if (isGlobalVar && "Window".equals(variableName)
1122 :           && type instanceof FunctionType
1123 :           && type.isConstructor()) {
1124 :         FunctionType globalThisCtor =
1125 :             typeRegistry.getNativeObjectType(GLOBAL_THIS).getConstructor();
1126 :         globalThisCtor.getInstanceType().clearCachedValues();
1127 :         globalThisCtor.getPrototype().clearCachedValues();
1128 :         globalThisCtor
1129 :             .setPrototypeBasedOn(((FunctionType) type).getInstanceType());
1130 :       }
1131 :     }"

"506 :   void expectUndeclaredVariable(String sourceName, Node n, Node parent, Var var,
507 :       String variableName, JSType newType) {
508 :     boolean allowDupe = false;
509 :     if (n.getType() == Token.GETPROP ||
510 :         NodeUtil.isObjectLitKey(n, parent)) {
511 :       JSDocInfo info = n.getJSDocInfo();
512 :       if (info == null) {
513 :         info = parent.getJSDocInfo();
514 :       }
515 :       allowDupe =
516 :           info != null && info.getSuppressions().contains("duplicate");
517 :     }
518 : 
519 :     JSType varType = var.getType();
520 : 
521 :     // Only report duplicate declarations that have types. Other duplicates
522 :     // will be reported by the syntactic scope creator later in the
523 :     // compilation process.
524 :     if (varType != null &&
525 :         varType != typeRegistry.getNativeType(UNKNOWN_TYPE) &&
526 :         newType != null &&
527 :         newType != typeRegistry.getNativeType(UNKNOWN_TYPE)) {
528 :       // If there are two typed declarations of the same variable, that
529 :       // is an error and the second declaration is ignored, except in the
530 :       // case of native types. A null input type means that the declaration
531 :       // was made in TypedScopeCreator#createInitialScope and is a
532 :       // native type.
533 :       if (var.input == null) {
534 :         n.setJSType(varType);
535 :         if (parent.getType() == Token.VAR) {
536 :           if (n.getFirstChild() != null) {
537 :             n.getFirstChild().setJSType(varType);
538 :           }
539 :         } else {
540 :           Preconditions.checkState(parent.getType() == Token.FUNCTION);
541 :           parent.setJSType(varType);
542 :         }
543 :       } else {
544 :         // Always warn about duplicates if the overridden type does not
545 :         // match the original type.
546 :         //
547 :         // If the types match, suppress the warning iff there was a @suppress
548 :         // tag, or if the original declaration was a stub.
549 :         if (!(allowDupe ||
550 :               var.getParentNode().getType() == Token.EXPR_RESULT) ||
551 :             !newType.equals(varType)) {
552 :           if (shouldReport) {
553 :             compiler.report(
554 :                 JSError.make(sourceName, n, DUP_VAR_DECLARATION,
555 :                     variableName, newType.toString(), var.getInputName(),
556 :                     String.valueOf(var.nameNode.getLineno()),
557 :                     varType.toString()));
558 :           }
559 :         }
560 :       }
561 :     }
562 :   }"

"370 :   boolean expectCanAssignTo(NodeTraversal t, Node n, JSType rightType,
371 :       JSType leftType, String msg) {
372 :     if (!rightType.canAssignTo(leftType)) {
373 :       if (bothIntrinsics(rightType, leftType)) {
374 :         // We have a superior warning for this mistake, which gives you
375 :         // the line numbers of both types.
376 :         registerMismatch(rightType, leftType);
377 :       } else {
378 :         mismatch(t, n, msg, rightType, leftType);
379 :       }
380 :       return false;
381 :     }
382 :     return true;
383 :   }"

"494 :   private void updateScopeForTypeChange(
495 :       FlowScope scope, Node left, JSType leftType, JSType resultType) {
496 :     Preconditions.checkNotNull(resultType);
497 :     switch (left.getType()) {
498 :       case Token.NAME:
499 :         String varName = left.getString();
500 :         Var var = syntacticScope.getVar(varName);
501 :         if (var != null && var.isLocal() && var.getScope() != syntacticScope) {
502 :           assignedOuterLocalVars.put(var.getScope(), var);
503 :         }
504 : 
505 :         // When looking at VAR initializers for declared VARs, we trust
506 :         // the declared type over the type it's being initialized to.
507 :         // This has two purposes:
508 :         // 1) We avoid re-declaring declared variables so that built-in
509 :         //    types defined in externs are not redeclared.
510 :         // 2) When there's a lexical closure like
511 :         //    /** @type {?string} */ var x = null;
512 :         //    function f() { x = 'xyz'; }
513 :         //    the inference will ignore the lexical closure,
514 :         //    which is just wrong. This bug needs to be fixed eventually.
515 :         boolean isVarDeclaration = left.hasChildren();
516 :         if (!isVarDeclaration || var == null || var.isTypeInferred()) {
517 :           redeclare(scope, varName, resultType);
518 :         }
519 :         left.setJSType(isVarDeclaration || leftType == null ?
520 :             resultType : null);
521 : 
522 :         if (var != null && var.isTypeInferred()) {
523 :           JSType oldType = var.getType();
524 :           var.setType(oldType == null ?
525 :               resultType : oldType.getLeastSupertype(resultType));
526 :         }
527 :         break;
528 :       case Token.GETPROP:
529 :         String qualifiedName = left.getQualifiedName();
530 :         if (qualifiedName != null) {
531 :           scope.inferQualifiedSlot(qualifiedName,
532 :               leftType == null ? getNativeType(UNKNOWN_TYPE) : leftType,
533 :               resultType);
534 :         }
535 : 
536 :         left.setJSType(resultType);
537 :         ensurePropertyDefined(left, resultType);
538 :         break;
539 :     }
540 :   }"

"1467 :   private void visitFunction(NodeTraversal t, Node n) {
1468 :     FunctionType functionType = (FunctionType) n.getJSType();
1469 :     String functionPrivateName = n.getFirstChild().getString();
1470 :     if (functionType.isConstructor()) {
1471 :       FunctionType baseConstructor = functionType.
1472 :           getPrototype().getImplicitPrototype().getConstructor();
1473 :       if (baseConstructor != null &&
1474 :           baseConstructor != getNativeType(OBJECT_FUNCTION_TYPE) &&
1475 :           (baseConstructor.isInterface() && functionType.isConstructor())) {
1476 :         compiler.report(
1477 :             t.makeError(n, CONFLICTING_EXTENDED_TYPE, functionPrivateName));
1478 :       } else {
1479 :         // All interfaces are properly implemented by a class
1480 :         for (JSType baseInterface : functionType.getImplementedInterfaces()) {
1481 :           boolean badImplementedType = false;
1482 :           ObjectType baseInterfaceObj = ObjectType.cast(baseInterface);
1483 :           if (baseInterfaceObj != null) {
1484 :             FunctionType interfaceConstructor =
1485 :               baseInterfaceObj.getConstructor();
1486 :             if (interfaceConstructor != null &&
1487 :                 !interfaceConstructor.isInterface()) {
1488 :               badImplementedType = true;
1489 :             }
1490 :           } else {
1491 :             badImplementedType = true;
1492 :           }
1493 :           if (badImplementedType) {
1494 :             report(t, n, BAD_IMPLEMENTED_TYPE, functionPrivateName);
1495 :           }
1496 :         }
1497 :         // check properties
1498 :         validator.expectAllInterfaceProperties(t, n, functionType);
1499 :       }
1500 :     } else if (functionType.isInterface()) {
1501 :       // Interface must extend only interfaces
1502 :       for (ObjectType extInterface : functionType.getExtendedInterfaces()) {
1503 :         if (extInterface.getConstructor() != null
1504 :             && !extInterface.getConstructor().isInterface()) {
1505 :           compiler.report(
1506 :               t.makeError(n, CONFLICTING_EXTENDED_TYPE, functionPrivateName));
1507 :         }
1508 :       }
1509 :       // Interface cannot implement any interfaces
1510 :       if (functionType.hasImplementedInterfaces()) {
1511 :         compiler.report(t.makeError(n,
1512 :             CONFLICTING_IMPLEMENTED_TYPE, functionPrivateName));
1513 :       }
1514 :       // Check whether the extended interfaces have any conflicts
1515 :       if (functionType.getExtendedInterfacesCount() > 1) {
1516 :         // Only check when extending more than one interfaces
1517 :         HashMap<String, ObjectType> properties
1518 :             = new HashMap<String, ObjectType>();
1519 :         HashMap<String, ObjectType> currentProperties
1520 :             = new HashMap<String, ObjectType>();
1521 :         for (ObjectType interfaceType : functionType.getExtendedInterfaces()) {
1522 :           currentProperties.clear();
1523 :           checkInterfaceConflictProperties(t, n, functionPrivateName,
1524 :               properties, currentProperties, interfaceType);
1525 :           properties.putAll(currentProperties);
1526 :         }
1527 :       }
1528 :     }
1529 :   }"

"896 :   private void updateTypeOfThisOnClosure(Node n, FunctionType fnType) {
897 :     // TODO(user): Make the template logic more general.
898 : 
899 :     if (fnType.getTemplateTypeName() == null) {
900 :       return;
901 :     }
902 : 
903 :     int i = 0;
904 :     int childCount = n.getChildCount();
905 :     // Find the parameter whose type is the template type.
906 :     for (Node iParameter : fnType.getParameters()) {
907 :       JSType iParameterType =
908 :           getJSType(iParameter).restrictByNotNullOrUndefined();
909 :       if (iParameterType.isTemplateType()) {
910 :         // Find the actual type of this argument.
911 :         JSType iArgumentType = null;
912 :         if (i + 1 < childCount) {
913 :           Node iArgument = n.getChildAtIndex(i + 1);
914 :           iArgumentType = getJSType(iArgument).restrictByNotNullOrUndefined();
915 :           if (!(iArgumentType instanceof ObjectType)) {
916 :             compiler.report(
917 :                 JSError.make(NodeUtil.getSourceName(iArgument), iArgument,
918 :                     TEMPLATE_TYPE_NOT_OBJECT_TYPE));
919 :             return;
920 :           }
921 :         }
922 : 
923 :         // Find the parameter whose type is function(this: T, ...)
924 :         boolean foundTemplateTypeOfThisParameter = false;
925 :         int j = 0;
926 :         for (Node jParameter : fnType.getParameters()) {
927 :           JSType jParameterType =
928 :               getJSType(jParameter).restrictByNotNullOrUndefined();
